def batch(sampler,plan,rows,role,start,n=64):
 x=[];y=[]
 for j,b,c in zip(plan[role+'_record'][start:start+n],plan[role+'_origin'][start:start+n],plan[role+'_channel'][start:start+n]):
  r=rows[int(j)];b=int(b);c=int(c);assert b-400>=r['local_start'] and b+5<=r['local_end_exclusive'];ar=sampler.array(r);x.append(ar[b-400:b,c]);y.append(ar[b:b+5,c])
 return torch.tensor(np.stack(x)[:,:,None],device='cuda'),torch.tensor(np.stack(y)[:,:,None],device='cuda')

