def evaluate(model,sampler,plan,rows,role,objective,cfg):
 model.eval();ls=[];arr={k:[] for k in ['prediction','target','history_scale','valid_target']}
 with torch.no_grad(),torch.random.fork_rng(devices=[0]):
  torch.manual_seed(cfg['mask_seed'])
  for start in range(0,len(plan[role+'_record']),64):
   x,y=batch(sampler,plan,rows,role,start);o=model(x);loss,_=objective(o,y);assert torch.isfinite(loss);ls.append(float(loss))
   for k,v in [('prediction',o['prediction']),('target',y),('history_scale',o['scale']),('valid_target',torch.isfinite(y))]:arr[k].append(v.cpu().numpy())
 return float(np.mean(ls)),{k:np.concatenate(v) for k,v in arr.items()}
